/* App Launcher — renders app cards from apps.json (generated by the workflow). */
"use strict";

(function () {
  const grid = document.getElementById("grid");
  const emptyEl = document.getElementById("empty");
  const emptyMsg = document.getElementById("emptyMsg");
  const search = document.getElementById("search");

  let apps = [];
  let loaded = false;

  // Deterministic hue for fallback letter tiles, from the app name.
  function hueFrom(name) {
    let h = 0;
    for (const ch of String(name)) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
    return h % 360;
  }

  function letterTileBackground(app) {
    const hue = hueFrom(app.name || app.title || "?");
    return `linear-gradient(135deg, hsl(${hue} 45% 45%), hsl(${(hue + 40) % 360} 55% 28%))`;
  }

  function buildTile(app) {
    const tile = document.createElement("div");
    tile.className = "tile";
    const initial = (app.title || app.name || "?").trim().charAt(0).toUpperCase();
    tile.textContent = initial;
    tile.style.background = letterTileBackground(app);

    if (app.icon) {
      const img = new Image();
      img.alt = "";
      img.onload = () => {
        tile.textContent = "";
        tile.style.background = "";
        tile.appendChild(img);
      };
      img.onerror = () => img.remove(); // keep the letter tile
      img.src = app.icon;
    }
    return tile;
  }

  function cardEl(app) {
    const a = document.createElement("a");
    a.className = "card";
    a.href = app.url;
    a.target = "_blank";
    a.rel = "noopener";

    const txt = document.createElement("div");
    txt.className = "card-txt";
    const title = document.createElement("div");
    title.className = "card-title";
    title.textContent = app.title || app.name;
    title.title = app.url;
    const desc = document.createElement("div");
    desc.className = "card-desc";
    desc.textContent = app.description || "";
    txt.append(title, desc);

    a.append(buildTile(app), txt);
    return a;
  }

  function render() {
    const q = (search.value || "").trim().toLowerCase();
    const qWords = q.split(/\s+/).filter(Boolean);
    const shown = apps.filter((app) => {
      if (qWords.length === 0) return true;
      const hay = (app.title + " " + app.name + " " + (app.description || "")).toLowerCase();
      return qWords.every((w) => hay.includes(w));
    });

    grid.innerHTML = "";
    for (const app of shown) grid.appendChild(cardEl(app));

    emptyEl.hidden = !(apps.length === 0 || (apps.length > 0 && shown.length === 0));
    if (apps.length === 0) {
      emptyMsg.innerHTML =
        loaded
          ? "No apps discovered yet.<br />Open this repo's <strong>Actions</strong> tab, run “<strong>Update app list</strong>” once, then reload."
          : "Loading…";
    } else if (shown.length === 0) {
      emptyMsg.textContent = `No apps match “${search.value.trim()}”.`;
    }
  }

  async function load() {
    try {
      const res = await fetch("apps.json", { cache: "no-store" });
      if (!res.ok) throw new Error(String(res.status));
      const data = await res.json();
      apps = Array.isArray(data.apps) ? data.apps : [];
    } catch (err) {
      apps = [];
    }
    loaded = true;
    render();
  }

  search.addEventListener("input", render);
  document.addEventListener("keydown", (e) => {
    if (e.key === "/" && document.activeElement !== search) {
      e.preventDefault();
      search.focus();
    }
  });
  window.addEventListener("hashchange", render);

  load();

  if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => {
      navigator.serviceWorker.register("sw.js").catch((err) => {
        console.warn("Service worker registration failed:", err);
      });
    });
  }
})();
